package sylva.ui;

import sylva.model.*;
import sylva.model.Rules.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;

/** Explanations and snapshots read directly from the current simulation structures. */
public final class InspectorDialog extends JDialog {
    private final GameEngine game;
    private final String[] names={"Queue","Linked list","Max heap","Enemy BST","Stacks","Upgrades","B-tree","BFS + grid"};
    private final String[] ids={"Circular queue","Singly linked list","Max heap","Binary search tree","Stack","Binary tree","B-tree","BFS"};
    private final JTabbedPane tabs=new JTabbedPane();
    public InspectorDialog(Window owner,GameEngine game){super(owner,"The living architecture",ModalityType.MODELESS);this.game=game;setDefaultCloseOperation(HIDE_ON_CLOSE);getContentPane().setBackground(Style.BG);setLayout(new BorderLayout(0,10));JPanel heading=new JPanel();heading.setOpaque(false);heading.setLayout(new BoxLayout(heading,BoxLayout.Y_AXIS));heading.setBorder(new EmptyBorder(17,18,0,18));heading.add(Style.eyebrow("THE SYSTEM BENEATH"));heading.add(Box.createVerticalStrut(5));heading.add(Style.title("The structures at work.",22));add(heading,BorderLayout.NORTH);for(int i=0;i<names.length;i++)tabs.addTab(names[i],panelFor(i));add(tabs,BorderLayout.CENTER);setSize(760,560);setLocationRelativeTo(owner);}
    public void refresh(){int selected=tabs.getSelectedIndex();for(int i=0;i<tabs.getTabCount();i++)tabs.setComponentAt(i,panelFor(i));tabs.setSelectedIndex(Math.max(0,selected));}
    private JPanel panelFor(int index){JPanel page=new JPanel(new BorderLayout(0,12));page.setBackground(Style.BG);page.setBorder(new EmptyBorder(16,18,18,18));JTextArea detail=new JTextArea(body(index));detail.setEditable(false);detail.setLineWrap(true);detail.setWrapStyleWord(true);detail.setBackground(Style.BG);detail.setForeground(Style.MUTED);detail.setFont(Style.font(12));page.add(new JScrollPane(detail),BorderLayout.CENTER);List<GameEngine.Operation> ops=game.operationsFor(ids[index]);JPanel bottom=new JPanel();bottom.setOpaque(false);bottom.setLayout(new BoxLayout(bottom,BoxLayout.Y_AXIS));bottom.add(Style.eyebrow("RECENT OPERATION · "+(ops.isEmpty()?"WAITING FOR ACTIVITY":ops.getLast().cost())));bottom.add(Box.createVerticalStrut(5));String message=ops.isEmpty()?"Start a wave or build a guardian to record this structure's real operations.":ops.getLast().name()+" — "+ops.getLast().explanation()+"\nAffected: "+String.join(" · ",ops.getLast().nodes());JTextArea op=new JTextArea(message);op.setLineWrap(true);op.setWrapStyleWord(true);op.setEditable(false);op.setBackground(Style.BG);op.setForeground(Style.TEXT);op.setFont(Style.font(11));bottom.add(op);page.add(bottom,BorderLayout.SOUTH);return page;}
    private String body(int index){return switch(index){
        case 0 -> "CIRCULAR FIFO QUEUE\n\nThe waiting enemy specifications for wave "+game.wave+" are stored in a fixed buffer. Head: "+game.queue.headIndex()+" · Tail: "+game.queue.tailIndex()+" · "+game.queue.size()+" / "+game.queue.capacity()+" pending.\n\n"+game.queue.values().stream().map(s->s.kind().name()+" ("+String.format("%.2f",s.delay())+"s)").toList()+"\n\nEnqueue and dequeue are O(1); capacity is checked before insertion. The same queue powers breadth-first route search.";
        case 1 -> "SINGLY LINKED LIST\n\n"+game.projectiles.size()+" live projectiles. Each is appended at the tail, then the entire list is traversed once each simulation step. Expired nodes are unlinked as the traversal goes.\n\n"+game.projectiles.values().stream().map(p->"#"+p.id+" · "+p.kind+" → enemy "+p.targetId).toList()+"\n\nTail append is O(1). Finding a specific node is O(P); filtering a traversal is O(P) total.";
        case 2 -> "MAX HEAP · LIVE TARGET PRIORITIES\n\nChoose a tower to see its current in-range targets. The heap is rebuilt from live enemy positions and that tower's chosen rule.\n\n"+game.heapTargets().stream().map(e->"enemy "+e.id+" · "+e.kind.name()+" · "+(int)e.hp+" health · progress "+String.format("%.2f",e.progress)).toList()+"\n\nThe heap root is the next target. Build costs O(n + k log k) when scanning n enemies and inserting k in-range targets; root extraction is O(log k).";
        case 3 -> "UNBALANCED BINARY SEARCH TREE\n\nThe tree indexes the exact mutable enemy instances used by the simulation. Current nodes (in order):\n\n"+game.indexedEnemies().stream().map(e->"enemy "+e.id+" · "+e.kind.name()+" · "+(int)e.hp+" health").toList()+"\n\nTree shape: "+game.enemyIndex.shape(e->e.id)+"\n\nSearch, insert, and delete cost O(h). Sequential IDs can skew the tree, so worst case is O(n).";
        case 4 -> "UNDO AND REDO STACKS\n\nUndo stack, newest first: "+game.undo.values().stream().map(d->d.kind()+" tower "+d.towerId()).toList()+"\n\nRedo stack, newest first: "+game.redo.values().stream().map(d->d.kind()+" tower "+d.towerId()).toList()+"\n\nEach player decision stores the before/after tower and a coin delta. Push, pop, and peek are O(1). Combat time and earned seeds are never rewound.";
        case 5 -> "BINARY UPGRADE TREE\n\n"+upgradeShape("root",0)+"\nA tower may choose only a child of its current node. Selecting Deep roots or Wild growth permanently moves the tower to that branch; the next two choices are shown in the live detail panel.\n\nDepth-first lookup is O(u) for u upgrade nodes.";
        case 6 -> "MINIMUM DEGREE 2 · B-TREE\n\n"+game.history.size()+" wave records stored · "+game.history.splits()+" node splits so far.\n"+game.btreeShape()+"\nEach node holds up to three sorted keys. A full child splits around its median, keeping all leaves at the same depth. Search/insertion are O(log n); traversal is O(n).";
        default -> "BREADTH-FIRST SEARCH · ROUTE GRID\n\n"+Rules.findRoute().order().size()+" cells visited · "+game.path.size()+" shortest-path cells.\n\n"+game.path.stream().map(c->"("+c.col()+","+c.row()+")").toList()+"\n\nA FIFO frontier explores orthogonal neighbors. A visited grid prevents repeated work; predecessor links rebuild the shortest route. Time and space: O(V + E) and O(V).";
    };}
    private String upgradeShape(String id,int depth){Upgrade u=Rules.upgrade(id);if(u==null)return "";return "  ".repeat(depth)+u.name+"  ["+u.cost+" seeds]"+(Rules.upgradeOptions(id).isEmpty()?"":"\n"+String.join("\n",Rules.upgradeOptions(id).stream().map(child->upgradeShape(child,depth+1)).toList()));}
}
